"""SkyyArmory 0.1.22 - PORT BUILD (Hytale 0.7.0). GENERATED by tools/armory_0_1_22_patch.py - edit the patch, never this file.
Run: python SkyyArmory/build_skyyarmory_0.1.22.py -> SkyyArmory/SkyyArmory-0.1.22.jar (never --deploy).
Harness: python SkyyArmory/test_skyyarmory_0.1.22.py --dir tools/dev/scratch/<task>/harness

0.1.22 = SkyyArmory-0.1.21.jar (the tools/deploy_set.py SET pin, built by build_skyyarmory_0.1.21.py on the 0.6 Assets.zip) with ONE
engine fix for the Hytale 0.7.0 release: SoulDrop.envOf's block fallback read BlockChunk.getEnvironment(III), gone in 0.7 (NoSuchMethodError
when a mob of unknown environment died). New SoulDrop.blockEnv reads the 0.7 EnvironmentSection the engine's way (chunk Ref loaded? ->
y outside 0..319 = 0 -> the section Ref at the block -> EnvironmentSection.get; WorldSupport.getEnvironmentId); envOf calls it. Every other
class and file is the 0.1.21 jar's, byte for byte, except the version texts (rules below) and manifest Version + Name.
WHY A PORT BUILD: the full build regenerates every item / particle / icon from the INSTALLED Assets.zip and the 0.7.0 assets changed the
vanilla sources it copies (staff InteractionVars, the Spectre_Void_Head particle system, the wand tap timing, ...) - porting those is a
design round of its own (notes in tools/armory_0_1_22_patch.py). NEXT ARMORY ROUND: derive from build_skyyarmory_0.1.21.py, port it to the
0.7 assets, and carry the SoulDrop change (tools/armory_0_1_22_patch.py rep blocks). This script needs SkyyArmory-0.1.21.jar (built jars
are not committed - it is the SET pin and lives in this folder / the deploy backups).
"""
import os, sys, json, zipfile, struct, shutil, hashlib
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, "..", "tools"))
import skyybuild as B

MOD, VERSION, OLD = "SkyyArmory", "0.1.22", "0.1.21"
PIN = os.path.join(HERE, "SkyyArmory-%s.jar" % OLD)
if not os.path.isfile(PIN):
    raise SystemExit("missing the SET pin jar " + PIN + " (build_skyyarmory_0.1.21.py builds it on the 0.6 assets only)")
TOKS = {'PKG': 'com.skyy.armory', 'CAC': 'com.hypixel.hytale.component.ComponentAccessor', 'CHS': 'com.hypixel.hytale.server.core.universe.world.storage.ChunkStore', 'CHU': 'com.hypixel.hytale.math.util.ChunkUtil', 'ENVA': 'com.hypixel.hytale.server.core.asset.type.environment.config.Environment', 'ESEC': 'com.hypixel.hytale.server.core.universe.world.chunk.section.EnvironmentSection', 'NPC': 'com.hypixel.hytale.server.npc.entities.NPCEntity', 'REF': 'com.hypixel.hytale.component.Ref', 'VEC': 'org.joml.Vector3d', 'WLD': 'com.hypixel.hytale.server.core.universe.world.World'}
BLOCKENV = 'public static int blockEnv(@WLD@ w, int x, int y, int z) {\n  if (w == null) return Integer.MIN_VALUE;\n  try {\n    @CHS@ cs = w.getChunkStore();\n    @REF@ c = cs.getChunkReference(@CHU@.indexChunkFromBlock(x, z));\n    if (c == null || !c.isValid()) return Integer.MIN_VALUE;\n    if (y < 0 || y >= 320) return 0;\n    @REF@ s = cs.getChunkSectionReferenceAtBlock(x, y, z);\n    if (s == null || !s.isValid()) return Integer.MIN_VALUE;\n    Object e = cs.getStore().getComponent(s, @ESEC@.getComponentType());\n    if (e instanceof @ESEC@) return ((@ESEC@) e).get(x, y, z);\n  } catch (Throwable t) { }\n  return Integer.MIN_VALUE;\n}'
ENVOF = 'public static String envOf(@CAC@ acc, @REF@ r, Object npc, @VEC@ p, @WLD@ w) {\n  java.util.Map seam = ENV;\n  if (seam != null) { Object o = seam.get(r); return o == null ? null : String.valueOf(o); }\n  int ei = Integer.MIN_VALUE;\n  try { if (npc instanceof @NPC@) ei = ((@NPC@) npc).getEnvironment(); } catch (Throwable t0) { ei = Integer.MIN_VALUE; }\n  if ((ei == Integer.MIN_VALUE || ei < 0) && w != null && p != null) {\n    try {\n      int x = (int) Math.floor(p.x);\n      int y = (int) Math.floor(p.y);\n      int z = (int) Math.floor(p.z);\n      ei = blockEnv(w, x, y, z);\n    } catch (Throwable t1) { ei = Integer.MIN_VALUE; }\n  }\n  if (ei == Integer.MIN_VALUE || ei < 0) return null;\n  try {\n    Object a = @ENVA@.getAssetMap().getAsset(ei);\n    if (a instanceof @ENVA@) return ((@ENVA@) a).getId();\n  } catch (Throwable t2) { }\n  return null;\n}'


def jv(src):
    import re
    def rep(m):
        if m.group(1) not in TOKS:
            raise SystemExit("unknown token @%s@" % m.group(1))
        return TOKS[m.group(1)]
    return re.sub(r"@([A-Z0-9]{2,7})@", rep, src)


# ---- the version texts: a class-file constant-pool rewrite of CONSTANT_Utf8 entries (same rules the 0.1.21 script's VERSION fills)
def cp_rewrite(b, fn):
    """b = class bytes; fn(str) -> str for every CONSTANT_Utf8 entry; returns (new bytes, changed count)."""
    n = struct.unpack(">H", b[8:10])[0]
    out, i, k, ch = [b[:10]], 10, 1, 0
    while k < n:
        t = b[i]
        if t == 1:
            ln = struct.unpack(">H", b[i + 1:i + 3])[0]
            raw = b[i + 3:i + 3 + ln]
            u = raw.decode("utf8", "surrogatepass") if b"\xc0\x80" not in raw and b"\xed" not in raw else None
            v = fn(u) if u is not None else None
            if v is not None and v != u:
                enc = v.encode("utf8")
                assert len(enc) < 65536
                out.append(b"\x01" + struct.pack(">H", len(enc)) + enc)
                ch += 1
            else:
                out.append(b[i:i + 3 + ln])
            i += 3 + ln
        else:
            size = {3: 5, 4: 5, 5: 9, 6: 9, 7: 3, 8: 3, 16: 3, 19: 3, 20: 3, 9: 5, 10: 5, 11: 5, 12: 5, 17: 5, 18: 5, 15: 4}[t]
            out.append(b[i:i + size])
            i += size
            if t in (5, 6):
                k += 1
        k += 1
    out.append(b[i:])
    return b"".join(out), ch


HITS = {"exact": 0, "pack": 0, "header": 0, "status": 0}


def version_text(cls):
    def fn(u):
        if u == OLD:
            HITS["exact"] += 1
            return VERSION
        v = u
        if "Skyy:%s SkyyArmory" % OLD in v:
            HITS["pack"] += v.count("Skyy:%s SkyyArmory" % OLD)
            v = v.replace("Skyy:%s SkyyArmory" % OLD, "Skyy:%s SkyyArmory" % VERSION)
        if "# SkyyArmory %s - settings (" % OLD in v:
            HITS["header"] += v.count("# SkyyArmory %s - settings (" % OLD)
            v = v.replace("# SkyyArmory %s - settings (" % OLD, "# SkyyArmory %s - settings (" % VERSION)
        if cls == "SkyyArmoryPlugin" and v.startswith(OLD + " "):
            HITS["status"] += 1
            v = VERSION + v[len(OLD):]
        return v
    return fn


# ---- SoulDrop: compile the 0.7 environment read against the 0.7 server jar + the pin jar's own classes
J = B.start()
pool = J["pool"]
pool.appendClassPath(PIN)
CtNewMethod = J["CtNewMethod"]
for cls, name, desc in (("com.hypixel.hytale.server.core.universe.world.storage.ChunkStore", "getChunkReference", "(J)Lcom/hypixel/hytale/component/Ref;"),
                        ("com.hypixel.hytale.server.core.universe.world.storage.ChunkStore", "getChunkSectionReferenceAtBlock", "(III)Lcom/hypixel/hytale/component/Ref;"),
                        ("com.hypixel.hytale.server.core.universe.world.storage.ChunkStore", "getStore", "()Lcom/hypixel/hytale/component/Store;"),
                        ("com.hypixel.hytale.component.Ref", "isValid", "()Z"),
                        ("com.hypixel.hytale.component.Store", "getComponent", "(Lcom/hypixel/hytale/component/Ref;Lcom/hypixel/hytale/component/ComponentType;)Lcom/hypixel/hytale/component/Component;"),
                        (TOKS["ESEC"], "getComponentType", "()Lcom/hypixel/hytale/component/ComponentType;"),
                        (TOKS["ESEC"], "get", "(III)I")):
    try:
        pool.get(cls).getMethod(name, desc)
    except Exception:
        raise SystemExit("API probe failed: %s.%s%s" % (cls, name, desc))
sd = pool.get("com.skyy.armory.SoulDrop")
assert not [m for m in sd.getDeclaredMethods() if str(m.getName()) == "blockEnv"], "the pin jar already has SoulDrop.blockEnv"
sd.addMethod(CtNewMethod.make(jv(BLOCKENV), sd))
_eo = [m for m in sd.getDeclaredMethods() if str(m.getName()) == "envOf"]
assert len(_eo) == 1, "SoulDrop.envOf"
sd.removeMethod(_eo[0])                 # the class file keeps no parameter names, so envOf is re-made whole (not setBody)
sd.addMethod(CtNewMethod.make(jv(ENVOF), sd))
SOULDROP = bytes(sd.toBytecode())

# ---- the jar: every pin entry, SoulDrop replaced, version texts, manifest Version + Name
OUT = B.class_out(HERE, "build_classes_port")
zin = zipfile.ZipFile(PIN)
extra = {}
for n in zin.namelist():
    b = zin.read(n)
    if n == "manifest.json":
        man = json.loads(b)
        assert man["Version"] == OLD and man["Name"] == "%s %s" % (OLD, MOD), man
        continue
    if n.endswith(".class"):
        if n == "com/skyy/armory/SoulDrop.class":
            b = SOULDROP
        b, _c = cp_rewrite(b, version_text(n.rsplit("/", 1)[1][:-6]))
        p = os.path.join(OUT, *n.split("/"))
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, "wb").write(b)
    else:
        extra[n] = b
assert HITS == {"exact": 3, "pack": 2, "header": 2, "status": 8}, "version texts: %s (want 3 / 2 / 2 / 8)" % HITS
man["Version"], man["Name"] = VERSION, "%s %s" % (VERSION, MOD)
jar = os.path.join(HERE, "%s-%s.jar" % (MOD, VERSION))
print("port build: pin %s (sha256 %s), SoulDrop + %d version texts, %d other files copied" % (
    os.path.basename(PIN), hashlib.sha256(open(PIN, "rb").read()).hexdigest()[:16], sum(HITS.values()), len(extra)))
B.assemble(jar, man, OUT, extra)
shutil.rmtree(OUT, ignore_errors=True)
